from math import fabs

# load employees
rate={}
with open('/app/dataset/employees.csv', newline='', encoding='utf-8') as f:
    for r in csv.DictReader(f): rate[r['PESEL']]=float(r['hourly_rate'])
unknown_map={'84731091580':'87031491580','62020111425':'65020111422','16102016795':'96102016751','68011910138':'68011810139','15720759071':'75020759171'}
# tasks
pay={939:500,961:500,561:500,146:500,447:500,304:300,956:300,964:300,959:300,123:290,946:290,385:290,987:290,148:290,387:140,452:140,867:140,978:140,253:160,590:160,900:160}
valid=list(pay)

def h(a,b): return sum(x!=y for x,y in zip(str(a),str(b)))

def inferred_pay(t):
    dists=[(h(t,v),pay[v]) for v in valid]
    mind=min(d for d,_ in dists)
    pays={p for d,p in dists if d==mind}
    if mind==1 and len(pays)==1:
        return next(iter(pays))
    return 0

errs={'recorded_bonus':[],'valid_only':[],'valid_plus_infer':[],'bonus_column_only':[]}
errs_invalid={'recorded_bonus':[],'valid_only':[],'valid_plus_infer':[],'bonus_column_only':[]}
