    emp=unknown_map.get(r['employee_id'],r['employee_id'])
    hr=float(r['hours_worked'])*rate[emp]
    sal=float(r['salary_amount'])
    bonus_col=float(r['bonus'])
    s=r['performed_tasks']
    if not s.startswith('['): s='['+s
    if not s.endswith(']'): s=s+']'
    tasks=ast.literal_eval(s)
    if not isinstance(tasks,list): tasks=[tasks]
    tasks=[int(x) for x in tasks]
    valid_only=sum(pay[t] for t in tasks if t in pay)
    valid_infer=valid_only+sum(inferred_pay(t) for t in tasks if t not in pay)
    rec=hr+bonus_col
    vals={'recorded_bonus':rec,'valid_only':hr+valid_only,'valid_plus_infer':hr+valid_infer,'bonus_column_only':sal}
    for k,v in vals.items():
        errs[k].append(abs(v-sal))
        if any(t not in pay for t in tasks):
            errs_invalid[k].append(abs(v-sal))

print('overall median abs diff to salary_amount')
for k,v in errs.items():
    print(k, statistics.median(v), statistics.mean(v))
print('\ninvalid-task rows median abs diff to salary_amount')
for k,v in errs_invalid.items():
    print(k, statistics.median(v), statistics.mean(v))
